#!/usr/bin/env python3
import argparse
import json
import re
from collections import defaultdict
from datetime import datetime, timezone
from pathlib import Path

ISO_Z = re.compile(r"Z$")


def parse_ts(value: str) -> datetime:
    if not value:
        raise ValueError("missing timestamp")
    normalized = ISO_Z.sub("+00:00", value)
    dt = datetime.fromisoformat(normalized)
    if dt.tzinfo is None:
        raise ValueError(f"timestamp must include timezone: {value}")
    return dt.astimezone(timezone.utc)


def load_events(path: Path):
    events = []
    with path.open(encoding="utf-8") as handle:
        for line_no, line in enumerate(handle, start=1):
            if not line.strip():
                continue
            record = json.loads(line)
            record["_line"] = line_no
            parse_ts(record["ts"])
            events.append(record)
    return events


def normalize_event(event):
    return {
        "ts": event.get("ts"),
        "host": event.get("host"),
        "user": event.get("user"),
        "event_type": event.get("event_type"),
        "src_ip": event.get("src_ip"),
        "dst_ip": event.get("dst_ip"),
        "domain": event.get("domain"),
        "process": event.get("process"),
        "parent_process": event.get("parent_process"),
        "raw_event": event,
    }


def authentication_bursts(events, threshold=5, window_seconds=900):
    failures = defaultdict(list)
    for event in events:
        if event.get("event_type") == "authentication_failure":
            failures[(event.get("user"), event.get("src_ip"))].append(event)

    findings = []
    for key, items in failures.items():
        items.sort(key=lambda e: parse_ts(e["ts"]))
        start = 0
        for end in range(len(items)):
            while (parse_ts(items[end]["ts"]) - parse_ts(items[start]["ts"])).total_seconds() > window_seconds:
                start += 1
            count = end - start + 1
            if count >= threshold:
                findings.append({
                    "type": "authentication_burst",
                    "user": key[0],
                    "src_ip": key[1],
                    "count": count,
                    "first_seen": items[start]["ts"],
                    "last_seen": items[end]["ts"],
                })
                break
    return findings


def suspicious_process_network(events):
    findings = []
    process_hosts = defaultdict(list)
    connections = defaultdict(list)
    for event in events:
        if event.get("event_type") == "process_start":
            process_hosts[event.get("host")].append(event)
        elif event.get("event_type") == "network_connection":
            connections[event.get("host")].append(event)

    for host, procs in process_hosts.items():
        for proc in procs:
            if proc.get("process") in {"powershell.exe", "cmd.exe", "script-host.exe"}:
                t0 = parse_ts(proc["ts"])
                for conn in connections.get(host, []):
                    delta = abs((parse_ts(conn["ts"]) - t0).total_seconds())
                    if delta <= 120:
                        findings.append({
                            "type": "process_network_correlation",
                            "host": host,
                            "process": proc.get("process"),
                            "parent_process": proc.get("parent_process"),
                            "dst_ip": conn.get("dst_ip"),
                            "ts": conn.get("ts"),
                        })
    return findings


def build_timeline(events, selected_hosts=None):
    rows = []
    for event in events:
        if selected_hosts and event.get("host") not in selected_hosts:
            continue
        rows.append(event)
    rows.sort(key=lambda e: parse_ts(e["ts"]))
    return rows


def analyze(events):
    normalized = [normalize_event(event) for event in events]
    bursts = authentication_bursts(events)
    proc_net = suspicious_process_network(events)
    affected_hosts = {item["host"] for item in proc_net if item.get("host")}
    affected_users = {item["user"] for item in bursts if item.get("user")}
    timeline = build_timeline(events, affected_hosts or None)
    return {
        "authentication_bursts": bursts,
        "process_network_correlations": proc_net,
        "affected_hosts": sorted(affected_hosts),
        "affected_users": sorted(affected_users),
        "timeline": timeline,
        "normalized_event_count": len(normalized),
    }


def main():
    parser = argparse.ArgumentParser(description="Synthetic SOC investigation lab")
    parser.add_argument("events", type=Path)
    parser.add_argument("--report", type=Path, default=Path("soc_report.json"))
    args = parser.parse_args()

    events = load_events(args.events)
    result = analyze(events)
    result["disposition_template"] = {
        "severity": "Set from impact + confidence + scope",
        "facts": "List observed evidence with timestamps",
        "hypotheses": "List interpretations that still need validation",
        "containment": "State authorized containment options",
        "recovery": "State validation and monitoring checks",
        "improvements": ["detection improvement", "telemetry improvement"],
    }
    args.report.write_text(json.dumps(result, indent=2), encoding="utf-8")
    print(json.dumps({
        "events": result["normalized_event_count"],
        "authentication_bursts": len(result["authentication_bursts"]),
        "process_network_correlations": len(result["process_network_correlations"]),
        "report": str(args.report),
    }, indent=2))


if __name__ == "__main__":
    main()

