import sys
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))
import soc_mini_lab


class SocLabTests(unittest.TestCase):
    def test_parse_ts_requires_timezone(self):
        with self.assertRaises(ValueError):
            soc_mini_lab.parse_ts("2026-09-07T12:00:00")

    def test_authentication_burst(self):
        events = []
        for i in range(5):
            events.append({
                "ts": f"2026-09-07T12:0{i}:00Z",
                "host": "ws-01",
                "user": "analyst",
                "event_type": "authentication_failure",
                "src_ip": "198.51.100.10",
            })
        result = soc_mini_lab.authentication_bursts(events, threshold=5)
        self.assertEqual(len(result), 1)
        self.assertEqual(result[0]["user"], "analyst")

    def test_process_network_correlation(self):
        events = [
            {
                "ts": "2026-09-07T12:00:00Z",
                "host": "ws-02",
                "event_type": "process_start",
                "process": "powershell.exe",
                "parent_process": "office-app.exe",
            },
            {
                "ts": "2026-09-07T12:01:00Z",
                "host": "ws-02",
                "event_type": "network_connection",
                "dst_ip": "203.0.113.20",
            },
        ]
        result = soc_mini_lab.suspicious_process_network(events)
        self.assertEqual(len(result), 1)
        self.assertEqual(result[0]["dst_ip"], "203.0.113.20")


if __name__ == "__main__":
    unittest.main()
